      "investment-trusts": { name: "Iontaobhais infheistíochta (dúnta, RA / AE)", taxTreatment: "CGC 31%; gan diúscairt bhréige", liquidity: "Laethúil", cap: "Dada", note: "Cuideachtaí dúnta liostaithe ar mhalartán, mar sin gearrtar cáin orthu go ginearálta mar scaireanna ag CGC 31%, le caillteanais infhritháirithe agus gan teagmhas ocht mbliana: an gnáthbhealach timpeall ar réimeas na gcistí in Éirinn. Deimhnigh láimhseáil an iontaobhais ar leith le comhairleoir cánach, mar is féidir le rialacha na gcistí amach ón gcósta roinnt struchtúr a ghabháil.", link: "CCPC: infheistíochtaí" },
      "unit-linked-life-fund": { name: "Ciste árachais saoil aonadnasctha (Zurich, Irish Life, New Ireland)", taxTreatment: "Cáin imeachta 35% + tobhach 1%", liquidity: "Pionós imeachta 5 bliana de ghnáth", cap: "Dada", note: "Simplí, le comhairle agus éagsúlaithe go maith, agus daor. Tobhach rialtais 1% ar an mbealach isteach, táille bhainistíochta bhliantúil 1% go 1.75% de ghnáth, móide cáin imeachta 35% agus an diúscairt bhréige. Tá fíorphraghas ar an áisiúlacht anseo.", link: "CCPC: infheistíochtaí" },
      "corporate-bonds": { name: "Bannaí sinsearacha corparáideacha / bainc", taxTreatment: "Cúpón ag an ráta imeallach; CGC 31% ar ghnóchain", liquidity: "Laethúil ach tanaí", cap: "Dada", note: "Toradh níos airde ná bannaí ceannasacha mar mhalairt ar riosca creidmheasa. Gearrtar suas le 52% ar an gcúpón, rud a fhágann gur droch-luach iad lasmuigh de phinsean agus i bhfad níos fearr laistigh de cheann.", link: "CCPC: infheistíochtaí" },
      "ires-reit": { name: "IRES REIT / maoin liostaithe", taxTreatment: "Dáiltí ag an ráta imeallach (creidmheas DWT 25%); CGC 31%", liquidity: "Laethúil", cap: "Dada", note: "An REIT Éireannach liostaithe deireanach agus an tiarna talún príobháideach is mó sa tír, le thart ar 3,900 aonad. Nochtadh maoine le leachtacht laethúil agus gan bhainistíocht, ach gearrtar cáin ar dháiltí REIT mar ioncam suas le 52%, ní ag rátaí CGC. Trádáladh é ag lascaine ar ghlanluach na sócmhainní agus tá sé ag ceannach scaireanna ar ais.", link: "IRES REIT" },
